mapper.select:
SELECT c.id AS capability_id,v.id AS version_id,v.version_number,p.name,p.description,s.state,s.revision
 FROM pf.capability c JOIN pf.capability_version v ON v.space_id=c.space_id AND v.owner_user_id=c.owner_user_id AND v.capability_id=c.id
 JOIN pf.skill_package_version p ON p.space_id=v.space_id AND p.owner_user_id=v.owner_user_id AND p.capability_id=v.capability_id AND p.version_id=v.id
 JOIN pf.capability_version_status s ON s.space_id=v.space_id AND s.owner_user_id=v.owner_user_id AND s.capability_id=v.capability_id AND s.version_id=v.id
WHERE c.space_id=#{actor.spaceId} AND c.owner_user_id=#{actor.userId} AND c.kind='SKILL' AND c.id=#{capability}
 AND v.version_number<#{before}
ORDER BY v.version_number DESC LIMIT #{limit}
